        tools: [["Excel / Google Sheets AI", "Հասանելի մաքրում, բանաձևեր, վերլուծություն և գծապատկերներ։"], ["ChatGPT Advanced Data Analysis", "Կոդով աջակցվող ուսումնասիրություն, պատկերում և վերարտադրելի արդյունքներ։"], ["Claude", "Մեծ փաստաթղթերի և տվյալների վերլուծություն՝ կառուցվածքային քննադատությամբ։"], ["Power BI / Tableau", "Իմաստային մոդելներ, վահանակներ և մշտադիտարկվող որոշումներ։"], ["Python + pandas", "Թափանցիկ, կրկնվող վերլուծություն և վավերացում։"], ["Power Query / Alteryx", "Կրկնվող պատրաստում և գործընթացների ավտոմատացում։"]],
